example.code:
using System.Windows;
using Devinno.UI.App;
using Devinno.UI.Styling;
using Devinno.UI.Wpf;

public sealed class MainWindow : Window
{
    private readonly DvApp _app = new() { Theme = DvTheme.Dark };

    public MainWindow()
    {
        Width = 1280; Height = 800;
        _app.Pages.Add(new MainPage());   // DvPage 를 상속한 페이지
        Content = new ViewControl { App = _app, ThemeWindow = true };
        // new ViewControl { App = _app, TouchMode = true } 는 터치 패널에서 가상 키보드를 쓴다
    }
}
